      "id": "P3",
      "text": "Endoscopist: Tomas Rivera-Lind, MD (fictional)"
    },
    {
      "id": "P4",
      "text": "Procedure: The colonoscope was advanced to the cecum."
    },
    {
      "id": "P5",
      "text": "The terminal ileum was not intubated."
    },
    {
      "id": "P6",
      "text": "Findings: A 9 mm sessile polyp was found in the descending colon at 40 cm."
    },
    {
      "id": "P7",
      "text": "The polyp was removed in one piece with a cold snare and retrieved."
    },
    {
      "id": "P8",
      "text": "No hot snare and no electrocautery were used on this polyp, and no submucosal injection was given."
    },
    {
      "id": "P9",
      "text": "Impression: 9 mm descending colon polyp removed by cold snare polypectomy."
    }
